// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import * as dotenv from 'dotenv';
import * as path from 'path';
import { defineConfig } from 'prisma/config';
import { getDotenvLoadOrder } from './src/config/env/env-file-paths';

// Mirror the Nest app's env resolution so Prisma CLI targets the expected DB per NODE_ENV.
for (const envPath of getDotenvLoadOrder()) {
  dotenv.config({
    path: path.resolve(__dirname, envPath),
    override: true,
  });
}

const databaseUrl = process.env['DATABASE_URL'];
if (!databaseUrl || databaseUrl.trim() === '') {
  throw new Error(
    'DATABASE_URL environment variable is required but not set. ' +
      'Please define it in your .env file (see docs/environment.md for reference).',
  );
}

export default defineConfig({
  schema: 'prisma/',
  migrations: {
    path: 'prisma/migrations',
  },
  datasource: {
    url: databaseUrl,
  },
});
